mapper.update:
UPDATE account_mfa
SET status = 'ENABLED',
    enabled_at = #{enabledAt},
    gmt_modified = #{enabledAt}
WHERE account_type = #{accountType}
  AND account_id = #{accountId}
  AND is_deleted = 0

UPDATE account_mfa
SET is_deleted = 1,
    gmt_deleted = #{gmtModified},
    gmt_modified = #{gmtModified}
WHERE account_type = #{accountType}
  AND account_id = #{accountId}
  AND is_deleted = 0
